#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse,shutil,subprocess\nfrom pathlib import Path\n\ndef main():\n ap=argparse.ArgumentParser();ap.add_argument("--output",type=Path,default=Path("dist/x86-runtime-v0.1/runtime.wasm"));ap.add_argument("--clang",default=shutil.which("clang"));a=ap.parse_args()\n if not a.clang:raise SystemExit("clang is required")\n root=Path(__file__).resolve().parents[1];src=root/"runtime/x86/runtime.c";a.output.parent.mkdir(parents=True,exist_ok=True)\n cmd=[a.clang,"--target=wasm32","-O2","-nostdlib",str(src),"-o",str(a.output),"-Wl,--no-entry","-Wl,--export-all","-Wl,--export-memory","-Wl,--import-memory","-Wl,--initial-memory=1048576","-Wl,--max-memory=268435456"]\n subprocess.run(cmd,check=True);print(f"Built {a.output}")\nif __name__=="__main__":main()\n